// Turn each hot contact into a deal request. Edit the two constants if your pipeline differs.
// Internal IDs: HubSpot Settings > Objects > Deals > Pipelines. Free default pipeline: 'default' / 'appointmentscheduled'.
const PIPELINE = 'default';
const STAGE = 'appointmentscheduled';

const contacts = $input.first().json.results ?? [];
return contacts.map((c) => {
  const p = c.properties || {};
  const name = `${p.firstname ?? ''} ${p.lastname ?? ''}`.trim() || p.email || `Contact ${c.id}`;
  // The deal name doubles as the dedupe key: one deal per lead.
  const dealname = `${name}${p.company ? ' - ' + p.company : ''} (Inbound)`;
  return { json: {
    contact_id: c.id,
    dealname,
    search_body: {
      filterGroups: [{ filters: [{ propertyName: 'dealname', operator: 'EQ', value: dealname }] }],
      properties: ['dealname'],
      limit: 1,
    },
    deal_body: {
      properties: { dealname, pipeline: PIPELINE, dealstage: STAGE },
      // 3 = deal-to-contact association (HubSpot defined)
      associations: [{ to: { id: c.id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 3 }] }],
    },
  } };
});

// Find open deals with no activity for STALL_DAYS or more and build one Slack message.
// Set STALL_DAYS = 0 temporarily to test with fresh deals. Set ALWAYS_POST = true to also post "all clear".
const STALL_DAYS = 0;
const ALWAYS_POST = false;
const PORTAL_ID = '149491548';
const MAX_LINES = 15;
const STAGES = {
  appointmentscheduled: 'Appointment Scheduled', qualifiedtobuy: 'Qualified To Buy',
  presentationscheduled: 'Presentation Scheduled', decisionmakerboughtin: 'Decision Maker Bought-In',
  contractsent: 'Contract Sent',
};

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toMs = (t) => (t == null || t === '' ? NaN : /^\d+$/.test(String(t)) ? Number(t) : Date.parse(t));
const now = Date.now();
const open = ($input.first().json.results ?? []).map((d) => {
  const p = d.properties || {};
  // Last touch = the most recent of creation, last modification and last logged activity.
  const last = Math.max(...[p.createdate, p.hs_lastmodifieddate, p.notes_last_updated].map(toMs).filter(Number.isFinite));
  return { id: d.id, name: p.dealname || '(unnamed deal)', stage: STAGES[p.dealstage] ?? p.dealstage ?? 'unknown', days: (now - last) / 86400000 };
}).filter((d) => Number.isFinite(d.days));

const stalled = open.filter((d) => d.days >= STALL_DAYS).sort((a, b) => b.days - a.days);
if (!stalled.length && !ALWAYS_POST) return [];

const link = (d) => (PORTAL_ID !== 'YOUR_HUBSPOT_PORTAL_ID'
  ? ` <https://app.hubspot.com/contacts/${PORTAL_ID}/record/0-3/${d.id}|Open>` : '');
let text;
if (!stalled.length) {
  text = `:white_check_mark: No stalled deals. ${open.length} open deals, all active in the last ${STALL_DAYS} days.`;
} else {
  const lines = stalled.slice(0, MAX_LINES).map((d) =>
    `• *${esc(d.name)}*, ${esc(d.stage)}, ${Math.floor(d.days)} days without activity.${link(d)}`);
  const more = stalled.length > MAX_LINES ? `\n_...and ${stalled.length - MAX_LINES} more._` : '';
  text = `:hourglass_flowing_sand: *Stalled deals:* ${stalled.length} of ${open.length} open deals have had no activity for ${STALL_DAYS}+ days\n${lines.join('\n')}${more}`;
}
return [{ json: { stalled_count: stalled.length, open_count: open.length, slack_text: text } }];

// Keep only leads that do not have a deal yet. If a lookup result is missing, play safe and skip.
const prep = $('Prepare Deals').all();
const res = $input.all();
return prep
  .filter((p, i) => Number(res[i]?.json?.total ?? 1) === 0)
  .map((p) => ({ json: p.json }));
